import java.util.*;
final class Key {
 final int n; Key(int n){this.n=n;}
 public boolean equals(Object o){return o instanceof Key && n==((Key)o).n;}
 public int hashCode(){return Integer.hashCode(n);}
}
public class Program { public static void main(String[] args) { Key a=new Key(6), b=new Key(6); Set<Key> keys=new HashSet<>(); keys.add(a); keys.add(b); System.out.print((a==b)+":"+a.equals(b)+":"+keys.size()); }}

