public class Program {
 static class Counter { int n; synchronized void add(){n++;} }
 public static void main(String[] args) throws InterruptedException {
  Counter c=new Counter(); Runnable work=()->{for(int i=0;i<100;i++)c.add();};
  Thread a=new Thread(work),b=new Thread(work); a.start();b.start();a.join();b.join();System.out.print(c.n);
 }
}

